Modify two server files to handle the `thread.fork` command.

### 1. Command Invariants (`apps/server/src/orchestration/commandInvariants.ts`)

Add a new exported function `requireMessageInThread` that validates a message exists in a thread:

```typescript
export function requireMessageInThread(input: {
  readonly readModel: OrchestrationReadModel;
  readonly command: OrchestrationCommand;
  readonly threadId: ThreadId;
  readonly messageId: MessageId;
}): Effect.Effect<OrchestrationThread, OrchestrationCommandInvariantError> {
  const thread = findThreadById(input.readModel, input.threadId);
  if (!thread) {
    return Effect.fail(
      invariantError(input.command.type, `Thread '${input.threadId}' does not exist.`),
    );
  }
  const message = thread.messages.find((m) => m.id === input.messageId);
  if (!message) {
    return Effect.fail(
      invariantError(
        input.command.type,
        `Message '${input.messageId}' does not exist in thread '${input.threadId}'.`,
      ),
    );
  }
  return Effect.succeed(thread);
}
```

You'll need to add `MessageId` to the imports from `@t3tools/contracts`.

### 2. Decider (`apps/server/src/orchestration/decider.ts`)

Add `requireMessageInThread` to the imports from `./commandInvariants.ts`.

Add a new case in the switch statement (before the `default` case):

```typescript
case "thread.fork": {
  yield* requireProject({
    readModel,
    command,
    projectId: command.projectId,
  });
  const sourceThread = yield* requireMessageInThread({
    readModel,
    command,
    threadId: command.sourceThreadId,
    messageId: command.forkAtMessageId,
  });
  yield* requireThreadAbsent({
    readModel,
    command,
    threadId: command.threadId,
  });

  // Collect messages up to and including forkAtMessageId
  const forkMessageIndex = sourceThread.messages.findIndex(
    (m) => m.id === command.forkAtMessageId,
  );
  const copiedMessages = sourceThread.messages.slice(0, forkMessageIndex + 1);
  const copiedMessageIds = copiedMessages.map((m) => m.id);

  // Count existing forks at this message to determine fork number
  const existingForks = readModel.threads.filter(
    (t) =>
      t.forkSource?.threadId === command.sourceThreadId &&
      t.forkSource?.messageId === command.forkAtMessageId,
  );
  const forkNumber = existingForks.length + 1;

  return {
    ...withEventBase({
      aggregateKind: "thread",
      aggregateId: command.threadId,
      occurredAt: command.createdAt,
      commandId: command.commandId,
    }),
    type: "thread.forked",
    payload: {
      threadId: command.threadId,
      projectId: command.projectId,
      sourceThreadId: command.sourceThreadId,
      forkAtMessageId: command.forkAtMessageId,
      title: command.title,
      modelSelection: command.modelSelection,
      runtimeMode: command.runtimeMode,
      interactionMode: command.interactionMode,
      branch: command.branch,
      worktreePath: command.worktreePath,
      copiedMessageIds,
      forkNumber,
      createdAt: command.createdAt,
      updatedAt: command.createdAt,
    },
  };
}
```

IMPORTANT: The `default` case has `command satisfies never` â€” your new case MUST be added before it to ensure exhaustive type checking passes.

