### 2. Projector (`apps/server/src/orchestration/projector.ts`)

Add import of `ThreadForkedPayload` from `./Schemas.ts` (add to existing import block).

Add a new case in the `projectEvent` switch statement (add it after `thread.unarchived` and before `thread.meta-updated`, to keep logical grouping):

```typescript
case "thread.forked":
  return Effect.gen(function* () {
    const payload = yield* decodeForEvent(
      ThreadForkedPayload,
      event.payload,
      event.type,
      "payload",
    );

    // Find source thread to copy messages from
    const sourceThread = nextBase.threads.find(
      (entry) => entry.id === payload.sourceThreadId,
    );

    // Build messages for the new forked thread
    const copiedMessageIdSet = new Set(payload.copiedMessageIds as string[]);
    const copiedMessages: OrchestrationMessage[] = sourceThread
      ? sourceThread.messages
          .filter((msg) => copiedMessageIdSet.has(msg.id))
          .map((msg) => ({ ...msg }))
      : [];

    // Create the new forked thread
    const forkedThread: OrchestrationThread = yield* decodeForEvent(
      OrchestrationThread,
      {
        id: payload.threadId,
        projectId: payload.projectId,
        title: payload.title,
        modelSelection: payload.modelSelection,
        runtimeMode: payload.runtimeMode,
        interactionMode: payload.interactionMode,
        branch: payload.branch,
        worktreePath: payload.worktreePath,
        latestTurn: null,
        createdAt: payload.createdAt,
        updatedAt: payload.updatedAt,
        archivedAt: null,
        forkSource: {
          threadId: payload.sourceThreadId,
          messageId: payload.forkAtMessageId,
        },
        forks: [],
        deletedAt: null,
        messages: copiedMessages,
        proposedPlans: [],
        activities: [],
        checkpoints: [],
        session: null,
      },
      event.type,
      "forkedThread",
    );

    // Add fork info to the source thread's forks array
    const updatedThreads = nextBase.threads.map((thread) => {
      if (thread.id === payload.sourceThreadId) {
        return {
          ...thread,
          forks: [
            ...thread.forks,
            {
              sourceMessageId: payload.forkAtMessageId,
              forkedThreadId: payload.threadId,
              forkedThreadTitle: payload.title,
              forkNumber: payload.forkNumber,
            },
          ],
        };
      }
      return thread;
    });

    return {
      ...nextBase,
      threads: [...updatedThreads, forkedThread],
    };
  });
```

IMPORTANT: The existing `default: return Effect.succeed(nextBase);` case will handle unknown events gracefully, but the `thread.forked` case must come before it to be matched.

Create a new hook file `apps/web/src/hooks/useHandleForkThread.ts` that provides the fork dispatch + navigation logic.

Follow the patterns from `useHandleNewThread.ts` and `useThreadActions.ts`.

```typescript
import { type MessageId, type ThreadId } from "@t3tools/contracts";
import { useNavigate } from "@tanstack/react-router";
import { useCallback } from "react";
import { newCommandId, newThreadId } from "../lib/utils";
import { readNativeApi } from "../nativeApi";
import { useStore } from "../store";

export function useHandleForkThread() {
  const threads = useStore((store) => store.threads);
  const navigate = useNavigate();

  const handleForkThread = useCallback(
    async (sourceThreadId: ThreadId, forkAtMessageId?: MessageId) => {
      const sourceThread = threads.find((t) => t.id === sourceThreadId);
      if (!sourceThread) return;

      // If no messageId specified, use the last message
      const targetMessageId =
        forkAtMessageId ?? sourceThread.messages[sourceThread.messages.length - 1]?.id;
      if (!targetMessageId) return;

      // Count existing forks at this message for title numbering
      const existingForksAtMessage = sourceThread.forks.filter(
        (f) => f.sourceMessageId === targetMessageId,
      );
      const forkNumber = existingForksAtMessage.length + 1;
      const titleSuffix = forkNumber === 1 ? "" : ` (${forkNumber})`;
      const title = `Fork: ${sourceThread.title}${titleSuffix}`;

      const forkedThreadId = newThreadId();
      const api = readNativeApi();
      if (!api) return;

      await api.orchestration.dispatchCommand({
        type: "thread.fork",
        commandId: newCommandId(),
        sourceThreadId,
        forkAtMessageId: targetMessageId,
        threadId: forkedThreadId,
        projectId: sourceThread.projectId,
        title,
        modelSelection: sourceThread.modelSelection,
        runtimeMode: sourceThread.runtimeMode,
        interactionMode: sourceThread.interactionMode,
        branch: sourceThread.branch,
        worktreePath: sourceThread.worktreePath,
        createdAt: new Date().toISOString(),
      });

      await navigate({
        to: "/$threadId",
        params: { threadId: forkedThreadId },
      });
    },
    [threads, navigate],
  );

  return { handleForkThread };
}
```

Check `apps/web/src/lib/utils.ts` and `apps/web/src/nativeApi.ts` to confirm exact import paths for `newCommandId`, `newThreadId`, and `readNativeApi`.

Create a ForkBadge component and render it on messages that have been forked from.

### 1. Create `apps/web/src/components/chat/ForkBadge.tsx`

```typescript
import { GitForkIcon } from "lucide-react";
import type { ThreadForkInfo } from "@t3tools/contracts";
import type { ThreadId } from "@t3tools/contracts";
import { Badge } from "../ui/badge";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "../ui/popover";

interface ForkBadgeProps {
  forks: ThreadForkInfo[];
  onNavigate: (threadId: ThreadId) => void;
}

export function ForkBadge({ forks, onNavigate }: ForkBadgeProps) {
  if (forks.length === 0) return null;

  return (
    <Popover>
      <PopoverTrigger asChild>
        <Badge
          variant="outline"
          className="cursor-pointer gap-1 text-[10px] hover:bg-accent"
        >
          <GitForkIcon className="size-3" />
          Forked{forks.length > 1 ? ` (${forks.length})` : ""}
        </Badge>
      </PopoverTrigger>
      <PopoverContent className="w-56 p-2" align="start">
        <div className="space-y-1">
          <p className="px-1 text-xs font-medium text-muted-foreground">
            Forked threads
          </p>
          {forks
            .toSorted((a, b) => a.forkNumber - b.forkNumber)
            .map((fork) => (
              <button
                key={fork.forkedThreadId}
                type="button"
                className="w-full rounded-sm px-2 py-1.5 text-left text-xs hover:bg-accent"
                onClick={() => onNavigate(fork.forkedThreadId)}
              >
                {fork.forkedThreadTitle}
              </button>
            ))}
        </div>
      </PopoverContent>
    </Popover>
  );
}
```

Check if `Badge` and `Popover` components exist in `apps/web/src/components/ui/`. If `badge.tsx` or `popover.tsx` doesn't exist, check what's available and use alternatives (e.g., a simple styled button/span for badge, and a custom dropdown or the DropdownMenu for the popover).

